import{_ as a,o as l,c as n,aw as e}from"./chunks/framework.DLufY-ao.js";const h=JSON.parse('{"title":"SQL инъекции","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/network/network/hacking/sql-injection.md","filePath":"wiki/dev-commit/network/network/hacking/sql-injection.md"}'),o={name:"wiki/dev-commit/network/network/hacking/sql-injection.md"};function t(i,s,r,p,c,d){return l(),n("div",null,[...s[0]||(s[0]=[e(`<h1 id="sql-инъекции" tabindex="-1">SQL инъекции <a class="header-anchor" href="#sql-инъекции" aria-label="Permalink to &quot;SQL инъекции&quot;">​</a></h1><ul><li><strong>SQL инъекции</strong> - один из самых доступных способов взлома сайта</li><li>Суть таких инъекций - внедрение в данные (передаваемые через GET, POST запросы или значения Cookie) произвольного SQL кода. Если сайт уязвим и выполняет такие инъекции, то по сути есть возможность творить с БД (чаще всего это MySQL) что угодно</li></ul><h2 id="способы-борьбы" tabindex="-1">Способы борьбы <a class="header-anchor" href="#способы-борьбы" aria-label="Permalink to &quot;Способы борьбы&quot;">​</a></h2><ul><li><strong>Parametrised Queries (Параметризованные запросы)</strong> - разделяют SQL-код и пользовательские данные, передавая их отдельно. Это не позволяет злоумышленнику внедрить вредоносные SQL-команды в запрос, так как данные всегда обрабатываются как значения, а не как исполняемый код.</li><li>Фильтрует SQL инъекции</li></ul><h3 id="принцип-работы" tabindex="-1">Принцип работы <a class="header-anchor" href="#принцип-работы" aria-label="Permalink to &quot;Принцип работы&quot;">​</a></h3><ul><li>Разделение кода и данных: Вместо того, чтобы напрямую вставлять пользовательский ввод в SQL-строку, используются заполнители (плейсхолдеры).</li><li>Отдельная передача данных: Пользовательские данные передаются в базу данных отдельно от самого SQL-запроса, например, через объект PreparedStatement в Java.</li><li>Гарантия безопасности: База данных обрабатывает эти данные как значения, а не как часть SQL-кода. Даже если злоумышленник попытается ввести SQL-команды, они будут восприняты как обычные строки, а не как инструкции для базы данных.</li></ul><h3 id="пример" tabindex="-1">Пример <a class="header-anchor" href="#пример" aria-label="Permalink to &quot;Пример&quot;">​</a></h3><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#A0A1A7;font-style:italic;">// С параметризацией (безопасно)</span></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;">// ? — это заполнитель</span></span>
<span class="line"><span style="color:#986801;">SELECT</span><span style="color:#0184BC;"> *</span><span style="color:#986801;"> FROM</span><span style="color:#383A42;"> users </span><span style="color:#986801;">WHERE</span><span style="color:#383A42;"> login </span><span style="color:#0184BC;">=</span><span style="color:#0184BC;"> ?</span></span></code></pre></div><ul><li>В этом случае, при попытке ввода &#39; OR &#39;1&#39;=&#39;1&#39;, база данных обработает это как строку для поиска пользователя с логином &#39; OR &#39;1&#39;=&#39;1&#39;, а не как SQL-код.</li></ul><hr><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#A0A1A7;font-style:italic;">// Без параметризации (уязвимо)</span></span>
<span class="line"><span style="color:#986801;">SELECT</span><span style="color:#0184BC;"> *</span><span style="color:#986801;"> FROM</span><span style="color:#383A42;"> users </span><span style="color:#986801;">WHERE</span><span style="color:#383A42;"> login </span><span style="color:#0184BC;">=</span><span style="color:#50A14F;"> &#39; + username + &#39;</span><span style="color:#383A42;">;</span></span></code></pre></div><ul><li>Если username будет &#39; OR &#39;1&#39;=&#39;1, запрос превратится в SELECT * FROM users WHERE login = &#39;&#39; OR &#39;1&#39;=&#39;1&#39;, что позволит получить все записи из таблицы.</li><li>В этом случае, при попытке ввода &#39; OR &#39;1&#39;=&#39;1&#39;, база данных обработает это как строку для поиска пользователя с логином &#39; OR &#39;1&#39;=&#39;1&#39;, а не как SQL-код.</li></ul>`,12)])])}const y=a(o,[["render",t]]);export{h as __pageData,y as default};
